<?php
namespace Tests\Feature;
use App\Models\{AttendanceEvent,PerfilEmpresa,TrainingSession,User}; use App\Services\{TrainingAttendanceIntegrationService,TrainingAudienceResolverService,TrainingSessionService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use Tests\TestCase;
class TrainingSessionIntegrationTest extends TestCase { use DatabaseTransactions;
 public function test_extraordinary_session_and_attendance_event_are_company_scoped_and_idempotent():void{$user=User::whereNotNull('company_id')->first();if(!$user)$this->markTestSkipped('No existe usuario empresarial de prueba.');$service=app(TrainingSessionService::class);$session=$service->create(['title'=>'Prueba CAP-2','description'=>'Sesión de integración','training_type'=>'training','scheduled_start_at'=>now()->addDay(),'scheduled_end_at'=>now()->addDay()->addHour(),'planned_duration_minutes'=>60,'modality'=>'presential','location'=>'Sala','instructor_type'=>'internal','instructor_employee_id'=>null,'audience_type'=>'all_workers','audience_description'=>'Todos','requires_attendance'=>true,'requires_signature'=>true,'requires_material'=>false,'requires_execution_report'=>false,'extraordinary_reason'=>'Prueba técnica de sesión extraordinaria','extraordinary_origin'=>'other'],$user->company_id,$user->id);$service->schedule($session,$user->id);$integration=app(TrainingAttendanceIntegrationService::class);$first=$integration->freeze($session,$user->id);$second=$integration->freeze($session->fresh(),$user->id);$this->assertSame($first['event']->id,$second['event']->id);$this->assertSame(1,AttendanceEvent::where('attendable_type','training_session')->where('attendable_id',$session->id)->count());$this->assertSame($user->company_id,$first['event']->company_id);$this->assertTrue($first['event']->participants->every(fn($p)=>!$p->employee_id||$p->employee->company_id===$user->company_id));}
}
